"""Shipped purity contracts for graph regions, independent of memory placement.

A region reads its arguments and its complete module subtree, writes only fresh outputs,
uses the current stream, and has no observable host effect. Successful tracing does not
establish that contract. Unknown code remains eager around eligible descendants.
"""

from __future__ import annotations

import functools
import inspect
import sys
from collections.abc import Iterator
from typing import Any

# Only classes generated by this Runtime may unwrap to a trusted implementation. A
# package subclass cannot inherit a marker and thereby acquire its parent's contract.
WRAPPERS: dict[type, type] = {}


def safe(torch: Any, module: Any) -> bool:
    """Known library implementations, with no package hooks or overwritten forwards."""
    cls = WRAPPERS.get(type(module), type(module))
    if (
        cls.__call__ is not torch.nn.Module.__call__
        or cls._call_impl is not torch.nn.Module._call_impl
        or cls._wrapped_call_impl is not torch.nn.Module._wrapped_call_impl
    ):
        return False
    for sub in module.modules():
        if any(name in vars(sub) for name in ("_call_impl", "_wrapped_call_impl")) or (
            getattr(sub, "_compiled_call_impl", None) is not None
        ):
            return False
        if any(
            type(t) not in (torch.Tensor, torch.nn.Parameter)
            for t in (*sub.parameters(recurse=False), *sub.buffers(recurse=False))
        ):
            return False
        for hooks in (sub._forward_pre_hooks, sub._forward_hooks):
            if any(
                not getattr(h, "__module__", "").startswith("tensorfs.varena.")
                for h in hooks.values()
            ):
                return False
        for name in ("forward", "_conv_forward"):
            forward = vars(sub).get(name)
            if forward is None:
                continue
            if forward is vars(sub).get("_cozy_execution_forward"):
                original = inspect.unwrap(forward)
                base = WRAPPERS.get(type(sub), type(sub))
                if getattr(original, "__func__", original) is base.forward:
                    continue
                forward = original
            if not getattr(forward, "__module__", "").startswith(
                "cozy_runtime.internal.execution."
            ):
                return False
    simple = (
        torch.nn.Linear,
        torch.nn.Conv1d,
        torch.nn.Conv2d,
        torch.nn.Conv3d,
        torch.nn.LayerNorm,
        torch.nn.GroupNorm,
        torch.nn.RMSNorm,
        torch.nn.GELU,
        torch.nn.SiLU,
        torch.nn.ReLU,
    )
    if cls in simple:
        return (
            not getattr(module, "inplace", False)
            and cls.forward.__module__ == cls.__module__
            and cls.forward.__qualname__ == f"{cls.__qualname__}.forward"
        )
    from cozy_runtime.internal.encoding import leaves

    if cls is leaves._native_leaf_class(torch):
        return "linear" not in vars(module) and module.provider in leaves._NATIVE_OPS
    if cls is leaves._leaf_class(torch):
        forward = module._cozy_forward
        known = forward is leaves.Nvfp4NativeLeaf._forward or (
            isinstance(forward, functools.partial)
            and forward.func is leaves.MicroScaledNativeLeaf._forward
            and forward.args == (torch,)
            and not forward.keywords
        )
        return known and "linear" not in vars(module)
    if cls is torch.nn.Sequential:
        return all(safe(torch, child) for child in module.children())
    # These registered Diffusers implementations are token-wise pure in eval mode. A
    # subclass's custom forward is deliberately excluded even when its base has this name.
    impl = cls.forward
    owner = sys.modules.get(impl.__module__)
    declared = getattr(owner, impl.__qualname__.split(".")[0], None)
    return (
        cls is declared
        and not module.training
        and impl.__module__.startswith("diffusers.models.")
        and impl.__qualname__.split(".")[0]
        in {
            "FeedForward",
            "GELU",
            "GEGLU",
            "SwiGLU",
            "ApproximateGELU",
            "LinearActivation",
        }
        and all(_children_safe(torch, child) for child in module.children())
    )


def _children_safe(torch: Any, module: Any) -> bool:
    if WRAPPERS.get(type(module), type(module)) is torch.nn.Dropout:
        return not module.training or module.p == 0
    if type(module) in (torch.nn.ModuleList, torch.nn.ModuleDict):
        return all(_children_safe(torch, child) for child in module.children())
    return safe(torch, module)


def regions(torch: Any, root: Any, path: str = "") -> Iterator[tuple[str, Any]]:
    """Largest declared-safe subtrees; eager parents preserve Python phase/routing behavior."""
    if safe(torch, root):
        yield path, root
    else:
        for name, child in root.named_children():
            yield from regions(torch, child, f"{path}.{name}" if path else name)
